P={
 'athens2':('אתונה','"ההפך קרה לסולון, שהתקין את החוקים באתונה" (עמ׳ 12). הנקודה היא האקרופוליס. כאן תפס פיסיסטרטוס את השלטון ב-561/0, וכאן נצורו העריצים ב-511/0 (הרודוטוס 1.59.6; 5.64.2).','פליאדס 638356144'),
 'megara2':('מגרה','השכנה במערב. נלחמה עם אתונה על סלמיס (פלוטרכוס, סולון 8–10). לפי הרודוטוס, פיסיסטרטוס התפרסם במלחמה נגדה, כשכבש את ניסאיה (1.59.4).','פלוטרכוס, סולון 8–12; הרודוטוס 1.59.4; פליאדס 570468'),
 'nisaia':('ניסאיה','נמל מגרה. לפי פלוטרכוס, בזמן המהומות של פרשת קילון "האתונאים איבדו את ניסאיה" (סולון 12.3, תרגום חופשי). לפי הרודוטוס, פיסיסטרטוס כבש אותה מאוחר יותר (1.59.4).','פלוטרכוס, סולון 12.3; הרודוטוס 1.59.4; פליאדס 570508'),
 'salamis2':('סלמיס','האי שעליו נלחמו אתונה ומגרה. לפי פלוטרכוס, סולון החזיר אותו לאתונה, ופלוטרכוס מביא שתי גרסאות לכיבוש (סולון 8–9). אחר כך, בזמן פרשת קילון, האתונאים "גורשו שוב מסלמיס" (12.3, תרגום חופשי). בסוף שני הצדדים מינו ספרטנים לבוררים (10.1). המקורות חלוקים: לפי יוסטינוס, המפקד היה פיסיסטרטוס (2.8), ולפי ח"א, מי שאומר זאת "מדבר שטויות", כי הגילים לא מתאימים (17.2). הנקודה היא העיר של התקופה הקלאסית. לפי סטרבון, העיר הישנה פנתה לאיגינה ולדרום (9.1.9).','פלוטרכוס, סולון 8–12; סטרבון 9.1.9; יוסטינוס 2.8; ח"א 17.2; פליאדס 580100'),
 'kolias':('כף קוליאס','לפי הגרסה "העממית" אצל פלוטרכוס, סולון הפליג לכאן. נשות אתונה הקריבו כאן לדמטר, ונערים בבגדי נשים ובפגיונות הרגו את המגרים שירדו לחוף (סולון 8.4–6). בגרסה השנייה, סולון עגן בכף "הצופה אל אאובויה", שלא זוהתה (9.2). המקורות חלוקים: אצל יוסטינוס המגרים רצו לחטוף את נשות אתונה בטקסי אלאוסיס, והמפקד הוא פיסיסטרטוס (2.8). הנקודה של פליאדס נמצאת בים, ולכן הוזזה לחוף.','פלוטרכוס, סולון 8–9; יוסטינוס 2.8; פליאדס 579981'),
 'canopus2':('קנופוס','סולון עצמו כתב שישב "בשפכי הנילוס, ליד חוף קנופוס" (פלוטרכוס, סולון 26.1, תרגום חופשי). הנקודה בשפך של הזרוע המערבית של הנילוס.','פלוטרכוס, סולון 26.1; פליאדס 727097'),
 'sais':('סאיס','עירו של המלך אמסיס (אפלטון, טימאיוס 21e). לפי פלוטרכוס, סולון למד עם סונכיס מסאיס ועם פסנופיס מהליופוליס, ושמע מהם את סיפור אטלנטיס (סולון 26.1). לפי הרודוטוס, סולון לקח ממצרים את החוק של אמסיס, שכל אדם יצהיר כל שנה ממה הוא מתפרנס (2.177.2).','הרודוטוס 1.30.1; 2.177.2; פלוטרכוס, סולון 26.1; פליאדס 727217'),
 'soloi':('סולוי','לפי פלוטרכוס, סולון שכנע את המלך פילוקיפרוס להעביר את עירו למישור, והמלך קרא לה על שמו "סולוי" (סולון 26.2–3). זו מסורת: השם קדם לסולון, כי כתובת של אסרחדון מ-673–672 כבר מונה את "סילי". הרודוטוס מאשר רק את הביקור ואת השיר (5.113.2). המקורות חלוקים: לפי דיוגנס לארטיוס, סולון ייסד את סולוי שבקיליקיה (1.51).','פלוטרכוס, סולון 26; הרודוטוס 5.113.2; ד"ל 1.51; פליאדס 707624'),
 'sardis2':('סרדיס','בירת קרויסוס, מלך לודיה. כאן, לפי הרודוטוס, אמר סולון שהמאושר באדם הוא טלוס האתונאי, ושאין לקרוא לאדם מאושר לפני מותו (1.30–32). פלוטרכוס מודה ש"יש מי שמוכיחים לפי הכרונולוגיה" שהפגישה בדויה (סולון 27.1, תרגום חופשי).','הרודוטוס 1.30–33; פלוטרכוס, סולון 27; פליאדס 550867'),
 'eretria':('ארטריה','לכאן הלך פיסיסטרטוס בגלות השנייה (הרודוטוס 1.61.2). "הפרשים" ששלטו בארטריה תמכו בו (ח"א 15.2). מכאן יצא, "בשנה האחת-עשרה", ונחת במרתון (הרודוטוס 1.62.1, תרגום חופשי).','הרודוטוס 1.61–62; ח"א 15.2; פליאדס 579925'),
 'thebes_a':('תבאי','בארטריה אסף פיסיסטרטוס מתנות מהערים, ו"התבאים עלו על כולם בנתינת הכסף" (הרודוטוס 1.61.3, תרגום חופשי). ב-506 הבויאוטים פלשו לאטיקה וכבשו את אוינואה ואת היסיאי, ונוצחו ליד האוריפוס (5.74.2; 5.77.1).','הרודוטוס 1.61.3; 5.74–77; פליאדס 541138'),
 'argos_a':('ארגוס','שכירי חרב מארגוס באו לפיסיסטרטוס מהפלופונסוס (הרודוטוס 1.61.4). לפי ח"א, אשתו השנייה הייתה ארגיבית, ואלף ארגיבים לחמו בפאלנה (17.4).','הרודוטוס 1.61.4; ח"א 17.4; פליאדס 570106'),
 'marathon2':('מרתון','"ראשון באטיקה עגנו במרתון" (הרודוטוס 1.62.1, תרגום חופשי). כאן הצטרפו אל פיסיסטרטוס תומכים מהעיר ומהדמוסים. ב-490 הוביל היפיאס את הפרסים לכאן (6.102; 6.107).','הרודוטוס 1.62.1; 6.102; פליאדס 580021'),
 'pallenis':('מקדש אתנה פלניס','כאן נפגשו הצבאות. האתונאים היו אחרי ארוחת הצהריים, חלקם בקוביות וחלקם ישנים, ופיסיסטרטוס הבריח אותם (הרודוטוס 1.62.3–63.1). השנה המקובלת היא 546. המקורות חלוקים: Ruebel מציב את הקרב ב-534. המקדש של זמן הקרב לא נמצא. היסודות שנחשפו בסטברוס הם של מקדש מהמאה ה-5, שפורק בימי אוגוסטוס והועבר לאגורה.','הרודוטוס 1.62–63; פליאדס 42288211; Ruebel, GRBS 1973; archaeology.wiki'),
 'sparta_a':('ספרטה','ב-511/0 שלחה ספרטה את המלך קלאומנס לגרש את העריצים, אף שהיו ידידיה (הרודוטוס 5.63.2–64.1). לפי ח"א, הספרטנים זזו גם בגלל הידידות של העריצים עם ארגוס (19.4). ב-506 פלש קלאומנס שוב, כדי להפוך את איסגורס לעריץ (5.74.1).','הרודוטוס 5.63–74; ח"א 19.4; פליאדס 570685'),
 'sigeion':('סיגאיון','ליד שפך הסקמנדרוס. פיסיסטרטוס כבש אותה מאנשי מיטילנה, והושיב בה כעריץ את בנו הגסיסטרטוס (הרודוטוס 5.94.1). לכאן יצאו העריצים ב-511/0 (5.65.3). היפיאס השיא את בתו לבנו של עריץ למפסקוס, כי ראה שהם בעלי השפעה אצל דריווש (תוקידידס 6.59.3).','הרודוטוס 5.65.3; 5.94.1; תוקידידס 6.59.3–4; פליאדס 550877'),
 'delphi_a':('דלפי','"כפי שהאתונאים אומרים", האלקמאונידים שיחדו את הפיתיה, והיא אמרה לכל ספרטני ששאל: לשחרר את אתונה (הרודוטוס 5.63.1, תרגום חופשי). ח"א לא מזכיר שוחד (19.4).','הרודוטוס 5.62–63; ח"א 19.4; פליאדס 540726'),
 'eleusis2':('אלאוסיס','ב-506 הגיע לכאן קלאומנס עם צבא מכל הפלופונסוס. לפני הקרב עזבו הקורינתים, ואחריהם המלך השני, דמרטוס, ושאר בני הברית התפזרו (הרודוטוס 5.74–75).','הרודוטוס 5.74–75; פליאדס 579920'),
 'oinoe':('אוינואה','דמוס בקצה אטיקה, שהבויאוטים כבשו ב-506 (הרודוטוס 5.74.2). לא לבלבל עם אוינואה שליד מרתון.','הרודוטוס 5.74.2; פליאדס 580040'),
 'hysiai':('היסיאי','הרודוטוס קורא לאוינואה ולהיסיאי "הדמוסים הקיצוניים של אטיקה" (5.74.2, תרגום חופשי). אבל במקום אחר הוא קושר את היסיאי לפלטאיה (6.108.6), ופליאדס מציב אותה בבויאוטיה, ליד אריתראי. לכן היא לא צבועה כחלק מאטיקה.','הרודוטוס 5.74.2; 6.108.6; פליאדס 540831'),
 'chalcis':('כלקיס','ב-506 הכלקידים פשטו על אטיקה (הרודוטוס 5.74.2). האתונאים ניצחו את הבויאוטים ליד האוריפוס, ובאותו יום עברו לאאובויה וניצחו את הכלקידים. על האדמה של "בעלי הסוסים" של כלקיס יישבו 4,000 מתיישבים (5.77, תרגום חופשי).','הרודוטוס 5.74.2; 5.77; פליאדס 540703'),
}
